<?php require_once __DIR__.'/../includes/config.php';require_once __DIR__.'/../includes/db.php';require_once __DIR__.'/../includes/functions.php';require_once __DIR__.'/../includes/security.php';require_once __DIR__.'/../includes/auth.php';if(!isset($_SESSION['cart']))$_SESSION['cart']=[];if($_SERVER['REQUEST_METHOD']==='POST'){csrf_protect();$action=$_POST['action']??'';$id=(int)($_POST['product_id']??0);$qty=max(1,(int)($_POST['quantity']??1));if($action==='add')$_SESSION['cart'][$id]=($_SESSION['cart'][$id]??0)+$qty;if($action==='update')$_SESSION['cart'][$id]=$qty;if($action==='remove')unset($_SESSION['cart'][$id]);redirect('pages/cart.php');}$cart=[];$subtotal=0;if($_SESSION['cart']){$ids=array_keys($_SESSION['cart']);$in=implode(',',array_fill(0,count($ids),'?'));$st=$pdo->prepare("SELECT p.*,s.business_name FROM products p JOIN smes s ON s.id=p.sme_id WHERE p.id IN ($in)");$st->execute($ids);foreach($st as $p){$p['quantity']=(int)$_SESSION['cart'][$p['id']];$p['line_total']=$p['quantity']*$p['price'];$subtotal+=$p['line_total'];$cart[]=$p;}}$pageTitle='Cart';include __DIR__.'/../includes/partials/header.php';?><h1>Your Cart</h1><?php if(!$cart):?><p>Your cart is empty. <a href="products.php">Browse products</a>.</p><?php else:?><div class="cart-list"><?php foreach($cart as $p):?><div class="cart-item"><div><h3><?=e($p['name'])?></h3><p>Rs <?=number_format($p['price'],2)?> · <?=e($p['business_name'])?></p></div><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="product_id" value="<?=$p['id']?>"><input type="number" name="quantity" min="1" max="<?=$p['stock_quantity']?>" value="<?=$p['quantity']?>"><button name="action" value="update">Update</button><button name="action" value="remove">Remove</button></form><strong>Rs <?=number_format($p['line_total'],2)?></strong></div><?php endforeach;?></div><h2>Subtotal: Rs <?=number_format($subtotal,2)?></h2><a class="btn-primary" href="checkout.php">Proceed to Checkout</a><?php endif;?><?php include __DIR__.'/../includes/partials/footer.php';?>